/**
 * Define a color to be used for the given species.
 *
 * @param speciesType The species.
 * @param classColor The color to be used for the given species.
 * @param textColor The color to be used for the text in the class key.
 */
public void setColor(SpeciesType speciesType, Color classColor, Color textColor)
{
    colors.put(speciesType, classColor);

    // Creates label of the appropriate color and text to be
    // displayed by the class key.
    JLabel newClassLabel = new JLabel(speciesType.getDisplayName(), JLabel.CENTER);

    // Adjusts color of the label's text
    newClassLabel.setForeground(textColor);

    newClassLabel.setBackground(classColor);
    newClassLabel.setOpaque(true);

    classKey.add(newClassLabel);
}

/**
 * @param speciesType The species to get the colour of.
 * 
 * @return The color to be used for a given species.
 */
private Color getColor(SpeciesType speciesType)
{
    Color col = colors.get(speciesType);
    if(col == null) {
        // no color defined for this class
        return UNKNOWN_COLOR;
    }
    else {
        return col;
    }
}

/**
 * Show the current status of the field.
 * 
 * @param field The field whose status is to be displayed.
 */
public void showStatus(Field field)
{
    if(!isVisible()) {
        setVisible(true);
    }

    stepLabel.setText(STEP_PREFIX + Time.getStep());
    timeLabel.setText(TIME_PREFIX + getTimeString());
    weatherLabel.setText(WEATHER_PREFIX + Weather.getWeather() + "  ");
    stats.reset();

    fieldView.preparePaint();

    // Used to tally up the respective counts.
    int numberOfInfected = 0;
    int numberOfImmune = 0;

    for(int row = 0; row < field.getDepth(); row++) 
    {
        for(int col = 0; col < field.getWidth(); col++) 
        {
            Animal animal = (Animal) field.getObjectAt(row, col, Animal.class);
            Plant plant = (Plant) field.getObjectAt(row, col, Plant.class);

            if(animal != null) 
            {
                stats.incrementCount(animal.getSpeciesType());
                fieldView.drawMark(col, row, getColor(animal.getSpeciesType()));

                // Update the infected and immune counts
                if (animal.getIsInfected())
                {
                    numberOfInfected++;
                }

                if (animal.getIsImmune())
                {
                    numberOfImmune++;
                }
            }
            // Only show the plant if an animal is not present
            else if(plant != null) 
            {
                fieldView.drawMark(col, row, getColor(plant.getSpeciesType()));
            }
            else 
            {
                Color emptyColor = EMPTY_COLOR;
                fieldView.drawMark(col, row, emptyColor);
                fieldView.setBackground(emptyColor);
            }

            if (plant != null) 
            {
               stats.incrementCount(plant.getSpeciesType()); 
            }
        }
    }

    stats.countFinished();

    infectedLabel.setText(INFECTED_PREFIX + numberOfInfected);
    immuneLabel.setText(IMMUNE_PREFIX + numberOfImmune);

    population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
    fieldView.repaint();
}

/**
 * Determine whether the simulation should continue to run.
 * 
 * @param field The field to check viability.
 *
 * @return True if there is more than one species alive.
 */
public boolean isViable(Field field)
{
    return stats.isViable(field);
}

/**
 * @return Returns the properly formated time in 24 hr format.
 */
private String getTimeString()
{
    int time = Time.getTime();
    if (time >= 12){
        return time + ":00 ";
    }
    else {
        if(time<10){
            return "0" + time + ":00 ";
        }
        else {
            return time + ":00 ";
        }
    }
}

package savannah.model;

import java.util.EnumMap;
import java.util.Map;

/**
 * This class collects and provides some statistical data on the state 
 * of a field. It is flexible: it will create and maintain a counter 
 * for any class of object that is found within the field.
 *
 * @version 26/02/2022
 */
public class FieldStats
{
    // Counters for each type of entity (lion, zebra, etc.) in the simulation.
    private Map<SpeciesType, Counter> counters;
    // Whether the counters are currently up to date.
    private boolean countsValid;

    /**
     * Construct a FieldStats object.
     */
    public FieldStats()
    {
        // Set up a collection for counters for each type of animal that
        // we might find
        counters = new EnumMap<>(SpeciesType.class);
        countsValid = true;
    }

    /**
     * Get details of what is in the field.
     * 
     * @param field The field to get the population details of.
     * 
     * @return A string describing what is in the field.
     */
    public String getPopulationDetails(Field field)
    {
        StringBuilder buffer = new StringBuilder();
        if(!countsValid) {
            generateCounts(field);
        }
        for(SpeciesType key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        return buffer.toString();
    }

    /**
     * Invalidate the current set of statistics; reset all 
     * counts to zero.
     */
    public void reset()
    {
        countsValid = false;
        for(SpeciesType key : counters.keySet()) {
            Counter count = counters.get(key);
            count.reset();
        }
    }

    /**
     * Increment the count for one object.
     * 
     * @param speciesType The species to increment.
     */
    public void incrementCount(SpeciesType speciesType)
    {
        Counter count = counters.get(speciesType);
        if(count == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(speciesType.getDisplayName());
            counters.put(speciesType, count);
        }
        count.increment();
    }

    /**
     * Indicate that an animal count has been completed.
     */
    public void countFinished()
    {
        countsValid = true;
    }

    /**
     * Determine whether the simulation is still viable.
     * I.e., should it continue to run.
     * 
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) 
        {
            generateCounts(field);
        }

        for(SpeciesType key : counters.keySet()) 
        {
            Counter info = counters.get(key);
            if(info.getCount() > 0) 
            {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

    /**
     * Generate counts of the number of all species of 
     * animal and plant.
     * These are not kept up to date as animals and plants
     * are placed in the field, but only when a request
     * is made for the information.
     * 
     * @param field The field to generate the stats for.
     */
    private void generateCounts(Field field)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) 
        {
            for(int col = 0; col < field.getWidth(); col++) 
            {
                Animal animal = (Animal) field.getObjectAt(row, col, Animal.class);
                Plant plant = (Plant) field.getObjectAt(row, col, Plant.class);

                if(animal != null) 
                {
                    incrementCount(animal.getSpeciesType());
                }
                if (plant != null)
                {
                    incrementCount(plant.getSpeciesType());
                }
            }
        }

        countsValid = true;
    }
}

